CBU_st.name='CBU';
CBU_st.lat=35.62;
CBU_st.lon=140.06;
CBU_st.alt=0;
CBU_st.env='Coast';
CBU_st.footp='U';
%%
%read RR neph with CBU_read and  importfile_RRneph_CBU

%%
% CBU was received as monthly txt files and loaded via CBU_read and importfile_AE_CBU,
% importfile_tsineph_CBU and importfile_RRneph_CBU 
%adapt the parameter names 
TCBU_h = renamevars(TCBU_h, "Bsca", "BsB_S");
TCBU_h = renamevars(TCBU_h, "Gsca", "BsG_S");
TCBU_h = renamevars(TCBU_h, "Rsca", "BsR_S");
TCBU_h = renamevars(TCBU_h, "Bbck", "BbsB_S");
TCBU_h = renamevars(TCBU_h, "Gbck", "BbsG_S");
TCBU_h = renamevars(TCBU_h, "Rbck", "BbsR_S");
TCBU_h = renamevars(TCBU_h, "TI", "T");
TCBU_h = renamevars(TCBU_h, "x370nm", "Ba1_A");
TCBU_h = renamevars(TCBU_h, "x470nm", "Ba2_A");
TCBU_h = renamevars(TCBU_h, "x520nm", "Ba3_A");
TCBU_h = renamevars(TCBU_h, "x590nm", "Ba4_A");
TCBU_h = renamevars(TCBU_h, "x660nm", "Ba5_A");
TCBU_h = renamevars(TCBU_h, "x880nm", "Ba6_A");
TCBU_h = renamevars(TCBU_h, "x950nm", "Ba7_A");
% compute the daily median
CBU_rd=retime(TCBU_h,'daily',@nanmedian);
% RR neph has no backscattering
TCBU_RRSC_d.BbsG_SRR=[];
%% change scat unit from 1/km to 1/Mm
TCBU_RRSC_d.BsG_SRR=TCBU_RRSC_d.BsG_SRR.*1e3;
CBU_rd= outerjoin(CBU_rd, TCBU_RRSC_d);
names_rd=fieldnames(CBU_rd);
%%
first_date=CBU_rd.Time(1) %[output:0c3a072b]
last_date=CBU_rd.Time(end) %[output:4b1356d8]
names=fieldnames(CBU_rd);
c=startsWith(names,'Bs');
names_sc=names(c);
c=startsWith(names,'Bbs');
names_bsc=names(c);
c=endsWith(names,'A');
names_AE31=names(c);
prctile(CBU_rd.RH,[5 50 95]) % No control of RH, median=44%, 95 percontile=70% %[output:40268155]

plotFigControl(CBU_rd, CBU_st.name); %[output:6ea6b200] %[output:1fb383c9] %[output:3067f114] %[output:83d0ecd3] %[output:567da04a] %[output:434d11b4]
% it is not possible to plot Bbs, 
% 1 size cut, ok
% sc: ok, max in CBUmer, with negatives
%%
% break point detection
break_CBU_scat=change_point_analysis_V3(CBU_rd,names_sc,0.05,'CBU','neph SC'); %[output:38182156]
T_CBU_scat=make_table_breakpoints(break_CBU_scat,names_sc); %[output:6e62d515] %[output:16276752] %[output:096a8113] %[output:0c381021] %[output:29fbfd84] %[output:01c53002] %[output:5a53e72a] %[output:8aae498a] %[output:9eed9f9a] %[output:0b6787b4] %[output:6f65568a] %[output:017fdcbc]
%%

break_CBU_bscat=change_point_analysis_V3(CBU_rd,names_bsc(1:2,:),0.05,'CBU','neph BSC'); %[output:42dd2c15]
T_CBU_bscat=make_table_breakpoints(break_CBU_bscat,names_bsc(1:2,:)); %[output:306d5f38] %[output:39bdf698] %[output:72818c22] %[output:8f09d8b6] %[output:971ba245] %[output:176a6127] %[output:112b9c97] %[output:309b8f87] %[output:2ec60945] %[output:20dd9ae6] %[output:3ea0e3e2] %[output:67f318dd] %[output:597d4dad] %[output:2555e9f5] %[output:88a4fa8c] %[output:726c072a] %[output:484d1821] %[output:589590ab] %[output:6580098b] %[output:3e5a8143] %[output:2d4ab49c] %[output:7b4b23f6] %[output:74c0551c] %[output:0d1ce201] %[output:96f7c573] %[output:7bd3b5be] %[output:5dbd01df] %[output:8e9d48b1] %[output:7587e197] %[output:3afbad45] %[output:8050c523] %[output:03dcc2df] %[output:443f57fe] %[output:14839894] %[output:75a5d3dd] %[output:641b9d6c] %[output:091e2162] %[output:680404b0]
%%

break_CBU_abs=change_point_analysis_V3(CBU_rd,names_AE31,0.05,'CBU','AE31+AE33'); %[output:1d5d4b75]
T_CBU_abs=make_table_breakpoints(break_CBU_abs,names_AE31);
%%

lambdaAE7=[370 470 520 590 660 880 950];
%to compute exp A
CBU_cal=compute_exp_D(CBU_rd, names_AE31, lambdaAE7);
%%
plotFigControl_cal(CBU_cal, CBU_st.name);

%%

%problems: both neph are not homogeneous and cannot be used.


%%
CBU_tr=CBU_rd;
CBU_tr.y=year(CBU_tr.Time);
% begin at the beginning of a year: scat: 2012, 
%end 2020
P=timerange('2012-01-01','2021-01-01');
CBU_tr=CBU_tr(P,:);

%don't use both neph: not homogeneous
names=fieldnames(CBU_tr);
c= startsWith(names,["Bs";"Bbs";"U";"TS";"RH"])  %[output:8ae9273c]
N=names(c);
for i=1:length(N)
    CBU_tr.(N{i})=[];
end
 CBU_tr.P=[];
 CBU_tr.T=[];
CBU_tr=outerjoin(CBU_tr, CBU_cal);

%compute trend on AE 520 nm and expA_fit
CBU_tr.Ba1_A=[];
CBU_tr.Ba2_A=[];
CBU_tr.Ba4_A=[];
CBU_tr.Ba5_A=[];
CBU_tr.Ba6_A=[];
CBU_tr.Ba7_A=[];
CBU_tr.expA_bgAE=[];
CBU_tr.expA_brAE=[];
CBU_tr.expA_grAE=[];
%%
[CBU_result_MK,CBU_result_LMSlog,CBU_result_LMSlin]=all_trend_STN(CBU_tr,CBU_st); %[output:48324f4c]

writetable(CBU_result_MK,'CBU_res_MK.txt'); %, 'delimiter',',' )
writetable(CBU_result_LMSlog,'CBU_res_LMSlog.txt'); 
writetable(CBU_result_LMSlin,'CBU_res_LMSlin.txt'); 
%plot_10y_in_two(CBU_result_MK, CBU_st,'y');

